    def _on_notebook_configure(self, event: Any) -> None:
        """Notebook resize — re-render the top-bar usage label."""
        if event.widget is self._notebook:
            self._render_topbar_usage()

    def _notebook_tabs_end_x(self) -> int:
        """Return the rightmost pixel occupied by notebook tabs.

        Samples ``notebook.index("@x,y")`` across the width of the tab
        strip and returns the largest x that still resolves to a tab.
        Returns 0 if no tabs are detected or notebook is absent.
        """
        nb = self._notebook
        if nb is None:
            return 0
        width = nb.winfo_width()
        last_x = 0
        for x in range(0, max(width, 1), 4):
            try:
                nb.index(f"@{x},5")
            except tk.TclError:
                continue
            last_x = x
        return last_x

    def _render_topbar_usage(self) -> None:
        """No-op \u2014 usage display removed."""
        if hasattr(self, "_topbar_usage_var"):
            self._topbar_usage_var.set("")

    def _checkpoint(self) -> None:
        """Run git checkpoint in a background thread."""
        from personal_assistant_dashboard.checkpoint import run_checkpoint
        from personal_assistant_dashboard.config import WORK_DIR

        self._checkpoint_status_var.set("Running...")

        def _run() -> None:
            result = run_checkpoint(WORK_DIR)
            self._schedule(self._checkpoint_done, result.message, result.is_error)

        threading.Thread(target=_run, daemon=True).start()

    def _checkpoint_done(self, message: str, is_error: bool) -> None:
        """Update checkpoint status and auto-clear after 5 seconds."""
        self._checkpoint_status_var.set(message)
        self.log_console(
            f"Git checkpoint: {message}",
            "error" if is_error else "success",
            "",
            "",
        )
        self._root.after(5000, self._clear_checkpoint_status)

    def _clear_checkpoint_status(self) -> None:
        """Clear the checkpoint status label."""
        self._checkpoint_status_var.set("")

